INSERT INTO public.biblioteca_vectores (id,coleccion,materia,contenido,num_articulo,fuente,metadata,embedding,jurisdiccion,fuente_tipo,es_norma_vigente,revision_pendiente,instrumento_id,num_articulo_norm,hash_contenido,ingest_batch,ingested_at) VALUES
('OLA13_LPA_2014_01:LEY_PROCEDIMIENTO_ADMINISTRATIVO:149','mayalex_normativos','10_LEYES_REGLAMENTOS','El interesado deberá presentar nuevamente el reclamo administrativo cuando no hubiere presentado la correspondiente demanda judicial dentro de los sesenta (60) días siguientes a la notificación de la resolución negativa del reclamo, o en su caso, dentro del plazo de dos (2) meses contados a partir del vencimiento del plazo establecido en el artículo precedente.','149','Ley de Procedimiento Administrativo de Honduras (Decreto No. 152-87)','{"norm_id":"HN:LEY_PROCEDIMIENTO_ADMINISTRATIVO","instrumento_id":"LEY_PROCEDIMIENTO_ADMINISTRATIVO","ingest_batch":"OLA13_LPA_2014_01","ola":"OLA13","ordinal":151,"decreto":"152-87","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE PROCEDIMIENTOS ADMINISTRATIVO HONDURAS.pdf», con notas al pie de los D.255-2002 y D.268-2002; arts. 1, 6, 41, 61, 87, 88, 119, 123 y 126 según el D.266-2013 (La Gaceta 33,336).","pdf_sha256":"89e6a5dc851db2f49ba0b6971798df3eaf805b2f3835df4a8757c6b42c949d5a","article_sha256":"37b92fab1f5656ac27ef964be9c62e47a6439de7b6641435428f8f4826318c6a","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROCEDIMIENTO_ADMINISTRATIVO','149','37b92fab1f5656ac27ef964be9c62e47a6439de7b6641435428f8f4826318c6a','OLA13_LPA_2014_01',now()),
('OLA13_LPA_2014_01:LEY_PROCEDIMIENTO_ADMINISTRATIVO:150','mayalex_normativos','10_LEYES_REGLAMENTOS','Para la resolución de cuestiones no previstas expresamente en esta Ley, serán de aplicación supletoria los principios generales del procedimiento administrativo y, en su defecto, las normas del Código de Procedimientos Civiles, siempre que no fueren incompatibles con el régimen establecido por la misma.','150','Ley de Procedimiento Administrativo de Honduras (Decreto No. 152-87)','{"norm_id":"HN:LEY_PROCEDIMIENTO_ADMINISTRATIVO","instrumento_id":"LEY_PROCEDIMIENTO_ADMINISTRATIVO","ingest_batch":"OLA13_LPA_2014_01","ola":"OLA13","ordinal":152,"decreto":"152-87","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE PROCEDIMIENTOS ADMINISTRATIVO HONDURAS.pdf», con notas al pie de los D.255-2002 y D.268-2002; arts. 1, 6, 41, 61, 87, 88, 119, 123 y 126 según el D.266-2013 (La Gaceta 33,336).","pdf_sha256":"89e6a5dc851db2f49ba0b6971798df3eaf805b2f3835df4a8757c6b42c949d5a","article_sha256":"64b32fe92f2b427753884f88ec6962f2a33c9e94d9ae3251cef435111e6e1d00","ubicacion":["TITULO SEXTO","DISPOSICIONES FINALES Y TRANSITORIAS"],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROCEDIMIENTO_ADMINISTRATIVO','150','64b32fe92f2b427753884f88ec6962f2a33c9e94d9ae3251cef435111e6e1d00','OLA13_LPA_2014_01',now()),
('OLA13_LPA_2014_01:LEY_PROCEDIMIENTO_ADMINISTRATIVO:151','mayalex_normativos','10_LEYES_REGLAMENTOS','Las infracciones a la presente Ley se sancionarán con una multa de cien a mil lempiras, (L 100.00 a L 1000.00) atendiendo la gravedad de la falta, y se deducirán del sueldo mensual del infractor.

El órgano competente para aplicar las multas será el superior jerárquico del responsable de la falta y de no hacerlo aquél los órganos de control competentes lo incluirán como reparos o ajustes en sus informes respectivos, tanto al infractor como al superior jerárquico responsable.','151','Ley de Procedimiento Administrativo de Honduras (Decreto No. 152-87)','{"norm_id":"HN:LEY_PROCEDIMIENTO_ADMINISTRATIVO","instrumento_id":"LEY_PROCEDIMIENTO_ADMINISTRATIVO","ingest_batch":"OLA13_LPA_2014_01","ola":"OLA13","ordinal":153,"decreto":"152-87","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE PROCEDIMIENTOS ADMINISTRATIVO HONDURAS.pdf», con notas al pie de los D.255-2002 y D.268-2002; arts. 1, 6, 41, 61, 87, 88, 119, 123 y 126 según el D.266-2013 (La Gaceta 33,336).","pdf_sha256":"89e6a5dc851db2f49ba0b6971798df3eaf805b2f3835df4a8757c6b42c949d5a","article_sha256":"03605c482594c309367c94234839581151c3954ffa9f9d36b5f793231fea5990","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROCEDIMIENTO_ADMINISTRATIVO','151','03605c482594c309367c94234839581151c3954ffa9f9d36b5f793231fea5990','OLA13_LPA_2014_01',now()),
('OLA13_LPA_2014_01:LEY_PROCEDIMIENTO_ADMINISTRATIVO:152','mayalex_normativos','10_LEYES_REGLAMENTOS','Se deroga el Libro Segundo del Código de Procedimientos Administrativos de fecha cinco de abril de mil novecientos treinta y sus reformas.','152','Ley de Procedimiento Administrativo de Honduras (Decreto No. 152-87)','{"norm_id":"HN:LEY_PROCEDIMIENTO_ADMINISTRATIVO","instrumento_id":"LEY_PROCEDIMIENTO_ADMINISTRATIVO","ingest_batch":"OLA13_LPA_2014_01","ola":"OLA13","ordinal":154,"decreto":"152-87","texto_origen":"PDF_CONSOLIDADO_CEDIJ_SANEADO","edicion_fuente":"Edición del CEDIJ (Poder Judicial), «LEY DE PROCEDIMIENTOS ADMINISTRATIVO HONDURAS.pdf», con notas al pie de los D.255-2002 y D.268-2002; arts. 1, 6, 41, 61, 87, 88, 119, 123 y 126 según el D.266-2013 (La Gaceta 33,336).","pdf_sha256":"89e6a5dc851db2f49ba0b6971798df3eaf805b2f3835df4a8757c6b42c949d5a","article_sha256":"2d4549c83e6a1c26a997adaf9fd61ba2df6cba1a2679fa3d06f31c9dadcb0717","ubicacion":[],"constancias":[],"correcciones_saneamiento":["ENCABEZADO_RETIRADO"],"sustituye_id_legacy":null,"clasificacion_propuesta":{"vigencia":"VIGENTE","rol":null,"motivo":"PRIMARY elegible: edición consolidada CEDIJ con reformas integradas; cotejo íntegro con La Gaceta pendiente (D1)"},"revision_pendiente":true,"vigencia":"UNKNOWN"}'::jsonb,array_fill(0::real, ARRAY[384])::vector,'HN','codigo',NULL,true,'LEY_PROCEDIMIENTO_ADMINISTRATIVO','152','2d4549c83e6a1c26a997adaf9fd61ba2df6cba1a2679fa3d06f31c9dadcb0717','OLA13_LPA_2014_01',now()),
